globalThis.DLRewardAdventure={"start": {"text": "Sei al parco con un’amica. Su una panchina trovate una mappa con una stella. Quale strada volete seguire insieme?", "choices": [["Verso il laghetto", "pond"], ["Verso il giardino", "garden"]]}, "pond": {"text": "Nel laghetto nuota un’anatra. Sulla mappa leggete la parola ponte. Che cosa volete fare adesso?", "choices": [["Andare al ponte", "bridge"], ["Rileggere la mappa", "look"]]}, "garden": {"text": "Nel giardino ci sono fiori gialli. Una giardiniera indica un piccolo scaffale. Che cosa vi interessa?", "choices": [["Guardare lo scaffale", "books"], ["Chiedere informazioni sui fiori", "flowers"]]}, "bridge": {"text": "Sul ponte incontrate un amico con un quaderno da disegno. Insieme disegnate l’anatra. Il vostro percorso finisce con una nuova immagine.", "choices": []}, "look": {"text": "Sul retro della mappa c’è un invito a una lettura. Andate con la vostra amica alla biblioteca del parco. Comincia un pomeriggio tranquillo pieno di storie.", "choices": []}, "books": {"text": "Sullo scaffale ci sono libri da scambiare. Scegliete una storia di animali e in seguito riportate un vostro libro. La mappa diventa una nuova avventura di lettura.", "choices": []}, "flowers": {"text": "La giardiniera spiega come innaffiare i fiori. Aiutate con un piccolo annaffiatoio. Prima di salutarvi vi mostra un nuovo bocciolo.", "choices": []}};

